import { test, expect, Page, Browser } from '@playwright/test';
import * as path from 'path';

const auth = (role: string) => path.resolve(__dirname, `../../../auth/${role}.json`);
test.use({ storageState: auth('admin') });
test.describe.configure({ mode: 'serial' });

const TS = Date.now().toString().slice(-7);
const P = `QA-AUTO-pricing-${TS}`;
const SKU = `QA-AUTO-PR-${TS}`;
const G = `QA-AUTO-group-${TS}`;
const C = `QA-AUTO-customer-${TS}`;
let ready = false;

const ACTIONS = 'פעולות';
const custRow = (page: Page, name: string) =>
  page.getByRole('button').filter({ hasText: name }).filter({ has: page.getByRole('button', { name: ACTIONS }) }).first();
const plainRow = (page: Page, text: string) =>
  page.getByRole('main').locator('div').filter({ hasText: text }).filter({ has: page.getByRole('button', { name: ACTIONS }) }).last();
const productRow = (page: Page, name: string) =>
  page.getByRole('button', { name, exact: true }).locator(`xpath=ancestor::*[.//button[@aria-label="${ACTIONS}"]][1]`);

async function openGroups(page: Page) {
  await page.goto('/pricing/groups');
  await expect(page.getByRole('heading', { level: 1, name: 'קבוצות מוצרים' })).toBeVisible({ timeout: 20_000 });
  await expect(page.getByText('שם קבוצה', { exact: true })).toBeVisible();
}

async function openAssign(page: Page) {
  await plainRow(page, G).getByRole('button', { name: ACTIONS }).click();
  await page.getByRole('menuitem', { name: 'שיוך מוצרים' }).click();
  const dlg = page.getByRole('dialog');
  await expect(dlg.getByRole('heading', { name: `שיוך מוצרים · ${G}` })).toBeVisible();
  return dlg;
}

async function selectCustomer(page: Page, combobox: string, name: string) {
  await page.getByRole('combobox', { name: combobox }).click();
  await page.getByRole('option', { name: new RegExp(`^${name}`) }).click();
}

async function pricingFor(page: Page, name: string) {
  await page.goto('/pricing/customer');
  await expect(page.getByRole('heading', { level: 1, name: 'תמחור פר-לקוח' })).toBeVisible({ timeout: 20_000 });
  await selectCustomer(page, 'בחירת לקוח', name);
  const input = page.getByRole('spinbutton', { name: `מחיר ללקוח · ${P}` });
  await expect(input).toBeVisible({ timeout: 20_000 });
  return input;
}

async function asBuyer<T>(browser: Browser, fn: (page: Page) => Promise<T>): Promise<T> {
  const ctx = await browser.newContext({ storageState: auth('buyer'), locale: 'he-IL' });
  const page = await ctx.newPage();
  try {
    return await fn(page);
  } finally {
    await ctx.close();
  }
}

