// ---------- buyer («test») видит эффективную цену: cp-09 п.5, cp-10 п.6 ----------
const PA = `QA-AUTO-pricing-a${TS}`; // в группе G2
const PB = `QA-AUTO-pricing-b${TS}`; // вне группы
const G2 = `QA-AUTO-group-b${TS}`;
const BUYER_OPT = /^test\s*test · /; // клиент «test» = аккаунт buyer (не «testtest…»)
let ready2 = false;

async function pickBuyer(page: Page, combobox: string) {
  await page.getByRole('combobox', { name: combobox }).click();
  await page.getByRole('option', { name: BUYER_OPT }).click();
}

/** admin: «מחיר ללקוח» клиента «test» для PA; '' — убрать цену. Возвращает строку товара. */
async function setBuyerPrice(page: Page, value: string) {
  await page.goto('/pricing/customer');
  await expect(page.getByRole('heading', { level: 1, name: 'תמחור פר-לקוח' })).toBeVisible({ timeout: 20_000 });
  await pickBuyer(page, 'בחירת לקוח');
  const input = page.getByRole('spinbutton', { name: `מחיר ללקוח · ${PA}` });
  await expect(input).toBeVisible({ timeout: 20_000 });
  await input.fill(value);
  await page.getByRole('button', { name: 'שמירה', exact: true }).click();
  const row = input.locator(`xpath=ancestor::*[.//*[text()="QA-AUTO-PR-a${TS}"]][1]`);
  await expect(row).toContainText(value ? 'מותאם' : 'בסיס', { timeout: 15_000 });
  return row;
}

async function asAdmin<T>(browser: Browser, fn: (page: Page) => Promise<T>): Promise<T> {
  const ctx = await browser.newContext({ storageState: auth('admin'), locale: 'he-IL' });
  const page = await ctx.newPage();
  try {
    return await fn(page);
  } finally {
    await ctx.close();
  }
}

const card = (bp: Page, name: string) => bp.locator('article').filter({ hasText: name });
const cartLine = (bp: Page, name: string) =>
  bp.getByRole('button', { name: `הסרה מהעגלה — ${name}` }).locator('xpath=ancestor::*[contains(., "₪")][1]');
const cartTotal = (bp: Page) => bp.getByText('סה״כ משוער').locator('..');

async function shopCards(bp: Page) {
  await bp.goto('/shop');
  await bp.getByRole('searchbox', { name: 'חיפוש מוצר' }).fill(`QA-AUTO-pricing-`);
  await expect(card(bp, PA)).toHaveCount(1, { timeout: 20_000 });
  await expect(card(bp, PB)).toHaveCount(1);
}

async function openCart(bp: Page) {
  await bp.goto('/shop/cart');
  await expect(bp.getByRole('heading', { name: 'העגלה שלי' })).toBeVisible({ timeout: 20_000 });
  await expect(cartLine(bp, PA)).toBeVisible({ timeout: 15_000 });
}

test.describe('pricing אצל buyer («test»): מחיר פר-לקוח והנחת קבוצה (QA-AUTO)', () => {
  test.beforeAll(async ({ browser }) => {
    await asAdmin(browser, async (page) => {
      for (const [name, sku] of [[PA, `QA-AUTO-PR-a${TS}`], [PB, `QA-AUTO-PR-b${TS}`]]) {
        await page.goto('/catalog/new');
        await expect(page.getByRole('heading', { level: 1, name: 'מוצר חדש' })).toBeVisible({ timeout: 20_000 });
        await page.getByRole('textbox', { name: /שם מוצר/ }).fill(name);
        await page.getByRole('textbox', { name: /מק"ט/ }).fill(sku);
        await page.getByRole('spinbutton', { name: 'מחיר בסיס' }).fill('100');
        await page.getByRole('button', { name: 'שמירה', exact: true }).click();
        await expect(page.getByText('נוסף לקטלוג.').first()).toBeVisible({ timeout: 15_000 });
        // Остаток без места на складе — иначе «אזל» и нет «הוספה לעגלה».
        await page.goto('/catalog');
        await page.getByRole('textbox', { name: /חיפוש מוצר/ }).fill(name);
        const qty = page.getByRole('button', { name: `קליטת מלאי — ${name}`, exact: true });
        await qty.click({ timeout: 20_000 });
        const dlg = page.getByRole('dialog');
        await dlg.getByRole('spinbutton', { name: 'כמות', exact: true }).fill('5');
        await dlg.getByRole('button', { name: 'הוספה' }).click();
        await expect(qty).toHaveText('5', { timeout: 15_000 });
      }

      await page.goto('/pricing/groups');
      await expect(page.getByText('שם קבוצה', { exact: true })).toBeVisible({ timeout: 20_000 });
      await page.getByRole('button', { name: 'קבוצה חדשה' }).click();
      let dlg = page.getByRole('dialog');
      await dlg.getByRole('textbox', { name: /^שם קבוצה/ }).fill(G2);
      await dlg.getByRole('button', { name: 'שמירה' }).click();
      await expect(page.getByText(G2, { exact: true })).toBeVisible({ timeout: 15_000 });
      await plainRow(page, G2).getByRole('button', { name: ACTIONS }).click();
      await page.getByRole('menuitem', { name: 'שיוך מוצרים' }).click();
      dlg = page.getByRole('dialog');
      await dlg.getByRole('textbox', { name: 'חיפוש מוצר' }).fill(PA);
      await dlg.getByRole('checkbox', { name: PA }).click();
      await expect(dlg.getByRole('checkbox', { name: PA })).toBeChecked();
      await dlg.getByRole('button', { name: 'סיום' }).click();
      await expect(page.getByText(G2, { exact: true }).locator('xpath=following-sibling::*[1]')).toHaveText('1', { timeout: 15_000 });

      await setBuyerPrice(page, '80');

      await page.goto('/pricing/discounts');
      await expect(page.getByRole('heading', { level: 1, name: 'מחירונים והנחות' })).toBeVisible({ timeout: 20_000 });
      if (!(await page.getByRole('combobox', { name: 'קבוצת מוצרים' }).count()))
        await page.getByRole('button', { name: 'הנחה חדשה' }).click();
      await pickBuyer(page, 'לקוח');
      await page.getByRole('combobox', { name: 'קבוצת מוצרים' }).selectOption({ label: G2 });
      await page.getByRole('button', { name: '% אחוז' }).click();
      await page.getByRole('spinbutton', { name: 'אחוז הנחה' }).fill('10');
      await page.getByRole('button', { name: 'שמירה', exact: true }).click();
      await expect(plainRow(page, G2)).toContainText('10%', { timeout: 15_000 });
    });
    ready2 = true;
  });

  test.afterAll(async ({ browser }) => {
    // Корзина buyer: убрать только свои строки.
    await asBuyer(browser, async (bp) => {
      await bp.goto('/shop/cart');
      await expect(bp.getByRole('heading', { name: 'העגלה שלי' })).toBeVisible({ timeout: 20_000 });
      // ждём загрузку корзины: наши позиции либо пустая корзина
      await expect(
        bp.getByRole('button', { name: `הסרה מהעגלה — ${PA}` })
          .or(bp.getByRole('button', { name: `הסרה מהעגלה — ${PB}` }))
          .or(bp.getByText('העגלה ריקה'))
          .or(bp.getByRole('button', { name: /^הסרה מהעגלה/ }))
          .first(),
      ).toBeVisible({ timeout: 20_000 });
      for (const name of [PA, PB]) {
        const rm = bp.getByRole('button', { name: `הסרה מהעגלה — ${name}` });
        if (await rm.count()) {
          await rm.click();
          await expect(rm).toHaveCount(0, { timeout: 10_000 });
        }
      }
    });
    await asAdmin(browser, async (page) => {
      // Цена клиента «test» на PA.
      await page.goto('/pricing/customer');
      await expect(page.getByRole('heading', { level: 1, name: 'תמחור פר-לקוח' })).toBeVisible({ timeout: 20_000 });
      await pickBuyer(page, 'בחירת לקוח');
      const input = page.getByRole('spinbutton', { name: `מחיר ללקוח · ${PA}` });
      await expect(input).toBeVisible({ timeout: 20_000 }).catch(() => {});
      if ((await input.count()) && (await input.inputValue())) await setBuyerPrice(page, '');

      // Правило скидки «test» → G2.
      await page.goto('/pricing/discounts');
      await expect(page.getByRole('heading', { level: 1, name: 'מחירונים והנחות' })).toBeVisible({ timeout: 20_000 });
      const rule =() => page.getByRole('main').locator('div').filter({ hasText: G2 }).filter({ hasText: '10%' }).filter({ has: page.getByRole('button', { name: ACTIONS }) }).last();
      // ждём загрузку списка правил; если правила нет — удалять нечего
      await expect(rule()).toBeVisible({ timeout: 20_000 }).catch(() => {});
      while (await rule().count()) {
        await rule().getByRole('button', { name: ACTIONS }).click();
        await page.getByRole('menuitem', { name: 'מחיקה' }).click();
        await page.getByRole('dialog').getByRole('button', { name: 'מחיקה' }).click();
        await expect(page.getByRole('dialog')).toBeHidden({ timeout: 15_000 });
        await expect(rule()).toHaveCount(0, { timeout: 15_000 }).catch(() => {});
      }

      await openGroups(page);
      await expect(page.getByText(G2, { exact: true })).toBeVisible({ timeout: 20_000 }).catch(() => {});
      if (await page.getByText(G2, { exact: true }).count()) {
        await plainRow(page, G2).getByRole('button', { name: ACTIONS }).click();
        await page.getByRole('menuitem', { name: 'מחיקה' }).click();
        await page.getByRole('dialog').getByRole('button', { name: 'מחיקה' }).click();
        await expect(page.getByText(G2, { exact: true })).toHaveCount(0, { timeout: 15_000 });
      }

      for (const name of [PA, PB]) {
        await page.goto('/catalog');
        await page.getByRole('textbox', { name: /חיפוש מוצר/ }).fill(name);
        // ждём реальный результат поиска: строка товара либо «ничего не найдено»
        await expect(
          page.getByRole('button', { name, exact: true }).or(page.getByText('לא נמצאו מוצרים התואמים לסינון')),
        ).toBeVisible({ timeout: 20_000 });
        if (await page.getByRole('button', { name, exact: true }).count()) {
          await productRow(page, name).getByRole('button', { name: ACTIONS }).click();
          await page.getByRole('menuitem', { name: 'מחיקה' }).click();
          await page.getByRole('dialog').getByRole('button', { name: 'מחיקה' }).click();
          await expect(page.getByRole('button', { name, exact: true })).toHaveCount(0, { timeout: 15_000 });
        }
      }
    });
  });

  test('לקוח (buyer) רואה מחיר פר-לקוח בקטלוג ובעגלה, שינוי מיידי #6a38cf59 @desktop', async ({ browser }) => {
    test.skip(!ready2, 'QA-данные для buyer не созданы');
    await asBuyer(browser, async (bp) => {
      await shopCards(bp);
      await expect(card(bp, PA)).toContainText('₪80.00');
      await expect(card(bp, PA)).toContainText('מחירון אישי');
      await expect(card(bp, PB)).toContainText('₪100.00');
      await expect(card(bp, PB)).not.toContainText('מחירון אישי');
      for (const name of [PA, PB]) {
        await bp.getByRole('button', { name: `הוספה לעגלה — ${name}` }).click();
        await bp.waitForTimeout(1000);
      }
      await openCart(bp);
      await expect(cartLine(bp, PA)).toContainText('₪80.00');
      await expect(cartLine(bp, PB)).toContainText('₪100.00');
      await expect(cartTotal(bp)).toContainText('₪180.00');
    });

    await asAdmin(browser, async (page) => {
      const row = await setBuyerPrice(page, '70');
      await expect(row).toContainText('-30%');
    });
    await asBuyer(browser, async (bp) => {
      await openCart(bp);
      await expect(cartLine(bp, PA)).toContainText('₪70.00');
      await expect(cartTotal(bp)).toContainText('₪170.00');
      await shopCards(bp);
      await expect(card(bp, PA)).toContainText('₪70.00');
    });
  });

  test('הנחת קבוצה אצל buyer: ערך אפקטיבי אחד; בלי מחיר פר-לקוח ₪90; מוצר מחוץ לקבוצה/הוסר מהקבוצה — בלי הנחה #6a38cf59 #6a38cf58 @desktop', async ({ browser }) => {
    test.skip(!ready2, 'QA-данные для buyer не созданы');
    // Пересечение: цена פר-לקוח 95 (дороже, чем 100−10% = 90). Приоритет в документации не определён (D-10) —
    // проверяем только «одно значение, без суммирования (не ₪85.50)». Наблюдение 2026-10-03: побеждает מחיר פר-לקוח (₪95.00).
    await asAdmin(browser, (page) => setBuyerPrice(page, '95'));
    await asBuyer(browser, async (bp) => {
      await shopCards(bp);
      const text = await card(bp, PA).innerText();
      const prices = text.match(/₪\d+\.\d{2}/g) ?? [];
      expect(prices).toHaveLength(1);
      expect(['₪95.00', '₪90.00']).toContain(prices[0]);
      test.info().annotations.push({ type: 'D-10', description: `פר-לקוח 95 + קבוצה 10% → ${prices[0]}` });
      await openCart(bp);
      await expect(cartLine(bp, PA)).toContainText(prices[0]);
      await expect(cartLine(bp, PA)).not.toContainText('₪85.50');
      await expect(cartLine(bp, PB)).toContainText('₪100.00');
    });

    // Только скидка группы: 100 − 10% = ₪90.00; PB вне группы — базовая.
    await asAdmin(browser, (page) => setBuyerPrice(page, ''));
    await asBuyer(browser, async (bp) => {
      await shopCards(bp);
      await expect(card(bp, PA)).toContainText('₪90.00');
      await expect(card(bp, PB)).toContainText('₪100.00');
      await expect(card(bp, PB)).not.toContainText('מחירון אישי');
      await openCart(bp);
      await expect(cartLine(bp, PA)).toContainText('₪90.00');
      await expect(cartLine(bp, PB)).toContainText('₪100.00');
      await expect(cartTotal(bp)).toContainText('₪190.00');
    });

    // Товар убран из группы → скидка не действует.
    await asAdmin(browser, async (page) => {
      await openGroups(page);
      await plainRow(page, G2).getByRole('button', { name: ACTIONS }).click();
      await page.getByRole('menuitem', { name: 'שיוך מוצרים' }).click();
      const dlg = page.getByRole('dialog');
      await dlg.getByRole('textbox', { name: 'חיפוש מוצר' }).fill(PA);
      await dlg.getByRole('checkbox', { name: PA }).click();
      await expect(dlg.getByRole('checkbox', { name: PA })).not.toBeChecked();
      await dlg.getByRole('button', { name: 'סיום' }).click();
      await expect(page.getByText(G2, { exact: true }).locator('xpath=following-sibling::*[1]')).toHaveText('0', { timeout: 15_000 });
    });
    await asBuyer(browser, async (bp) => {
      await shopCards(bp);
      await expect(card(bp, PA)).toContainText('₪100.00');
      await openCart(bp);
      await expect(cartLine(bp, PA)).toContainText('₪100.00');
      await expect(cartTotal(bp)).toContainText('₪200.00');
    });
  });
});
